"use client";

/**
 * Photo orbit: pictures spiral in from the edges of the frame on one slow
 * orbit, shrinking and dimming as they near the centre, while a title holds
 * still in the middle.
 *
 * Written by Better Design. Painted from the theme prop; with no pictures each
 * tile shows a landscape placeholder drawn from the primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, interpolate, useCurrentFrame } from "remotion";
import { easings, mix, pickFont, progress, shiftHue, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

/** A bare file name resolves from the project's public folder; a URL or root path passes through. */

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin"] });

/** Frames the orbit takes to settle. The last 20 frames hold. */
const ORBIT_FRAMES = 118;
const STAGGER = 3;
const TILE_W = 340;
const TILE_H = 240;
const PLACEHOLDERS = 10;

/** Fixed paper and ink for placeholder photos, so they read the same in both modes. */
const LIGHT = "oklch(0.97 0.015 85)";
const DEEP = "oklch(0.3 0.05 60)";

export interface PhotoOrbitProps {
  /** The line that holds in the middle of the frame. */
  title?: string;
  /** Image URLs or static files. Placeholder tiles are drawn when empty. */
  pictures?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

/** A landscape drawn from the theme: tinted sky, a pale sun and two hills. */
function PlaceholderPhoto({ theme, index }: { theme: VideoTheme; index: number }) {
  const base = shiftHue(theme.primary, index * 47);
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", background: `linear-gradient(165deg, ${mix(base, LIGHT, 0.62)}, ${mix(base, LIGHT, 0.18)})` }}>
      <div style={{ position: "absolute", width: "26%", aspectRatio: "1", borderRadius: "50%", left: `${18 + (index * 23) % 50}%`, top: "16%", background: mix(base, LIGHT, 0.88) }} />
      <div style={{ position: "absolute", left: "-20%", right: "10%", bottom: "-38%", height: "80%", borderRadius: "50%", background: mix(base, DEEP, 0.28) }} />
      <div style={{ position: "absolute", left: "25%", right: "-30%", bottom: "-50%", height: "82%", borderRadius: "50%", background: mix(base, DEEP, 0.5) }} />
    </div>
  );
}

/** Pictures spiral toward a held title, smaller and dimmer as they arrive. */
export function PhotoOrbit({
  title = "Every moment, in one place",
  pictures = [],
  theme: themeOverride,
  font,
}: PhotoOrbitProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const count = pictures.length > 0 ? pictures.length : PLACEHOLDERS;

  const titleT = easings.out(progress(frame, 8, 26));

  const tiles = Array.from({ length: count }, (_, i) => {
    const start = i * STAGGER;
    const t = easings.out(progress(frame, start, ORBIT_FRAMES - start));
    // Each tile starts outside the frame and turns a third of a lap on the way in.
    const angle = (i / count) * Math.PI * 2 - Math.PI / 2 + (1 - t) * 2.1;
    const radius = interpolate(t, [0, 1], [1.0, 0]);
    const rx = 620 + radius * 760;
    const ry = 330 + radius * 420;
    const x = Math.cos(angle) * rx;
    const y = Math.sin(angle) * ry;
    const scale = interpolate(t, [0, 1], [1, 0.44]);
    const fade = interpolate(t, [0, 1], [1, 0.38]);
    const appear = progress(frame, start, 8);
    const tilt = Math.cos(angle) * -6 * (1 - t * 0.6);
    return { i, x, y, scale, opacity: fade * appear, tilt, depth: t };
  });

  // Tiles still far out sit over the ones that have settled near the title.
  const ordered = [...tiles].sort((a, b) => b.depth - a.depth);

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      <AbsoluteFill style={{ background: `radial-gradient(ellipse 46% 40% at 50% 50%, ${withAlpha(theme.primary, 0.08)}, transparent)` }} />
      {ordered.map(({ i, x, y, scale, opacity, tilt }) => (
        <div
          key={i}
          style={{
            position: "absolute",
            left: 960 - TILE_W / 2,
            top: 540 - TILE_H / 2,
            width: TILE_W,
            height: TILE_H,
            borderRadius: theme.radius * 1.4,
            overflow: "hidden",
            opacity,
            transform: `translate(${x}px, ${y}px) rotate(${tilt}deg) scale(${scale})`,
            boxShadow: `0 24px 60px oklch(0 0 0 / 0.16)`,
            border: `1px solid oklch(0 0 0 / 0.08)`,
            background: theme.card,
          }}
        >
          {pictures.length > 0 ? (
            <Img src={srcOf(pictures[i])} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          ) : (
            <PlaceholderPhoto theme={theme} index={i} />
          )}
        </div>
      ))}
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        <div
          style={{
            maxWidth: 1000,
            textAlign: "center",
            fontSize: 104,
            fontWeight: 700,
            lineHeight: 1.04,
            letterSpacing: "-0.035em",
            color: theme.foreground,
            opacity: titleT,
            transform: `translateY(${(1 - titleT) * 22}px)`,
            textWrap: "balance",
          }}
        >
          {title}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}
